# 行筛选：按条件把原表互补分割为满足条件/不满足条件两张表；支持中文大白话条件
# 列编号：按「筛选列」勾选顺序 = a、b、c…
import io
import ast
import re as _re
import numpy as np
import pandas as pd


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _is_empty(value):
    if value is None:
        return True
    if isinstance(value, float) and pd.isna(value):
        return True
    if isinstance(value, str):
        return value.strip() == ''
    return False


class _Empty:
    def __eq__(self, other):
        return _is_empty(other)

    def __ne__(self, other):
        return not _is_empty(other)

    def __repr__(self):
        return '空'


_EMPTY_ = _Empty()


def _mod_contains_(value, sub):
    if _is_empty(value):
        return False
    return str(sub) in str(value)


def _pretty(_seg):
    _s = _seg.replace('_EMPTY_', '空')
    _s = _re.sub(r"_mod_contains_\(([^,]+?),\s*('[^']*'|\"[^\"]*\")\)", r"\1 包含 \2", _s)
    return _s


