if _df.empty:
    raise RuntimeError('原始表是空的，没有行可分割')

_cols = {{filter_cols}}
if not isinstance(_cols, list) or not _cols:
    raise RuntimeError('请先在参数区选择至少一个筛选列（第一个 = a，第二个 = b…）')
if len(_cols) > 26:
    raise RuntimeError('最多选择 26 个筛选列（a~z）')
_column_names = [str(c) for c in _df.columns]
for _c in _cols:
    if _c not in _column_names:
        raise RuntimeError('筛选列「' + str(_c) + '」不在原始表中')

_raw_cond = {{drop_cond}}
if not isinstance(_raw_cond, str) or not _raw_cond.strip():
    raise RuntimeError('请填写分割条件。示例：a[i] <= 0；b[i] 包含 \'临时\'；c[i] in [\'北京\']；d[i] == 空；可用 and / or 组合')

_cond = _raw_cond
_cond = _cond.replace('== 空', '== _EMPTY_').replace('!= 空', '!= _EMPTY_')
_cond = _cond.replace('==空', '== _EMPTY_').replace('!=空', '!= _EMPTY_')
def _contains_repl(_m):
    return '_mod_contains_(' + _m.group(1) + '[' + _m.group(2) + '], ' + _m.group(3) + ')'
_cond = _re.sub(r"([a-z])\s*\[\s*([^\]]+?)\s*\]\s*包含\s*('[^']*'|\"[^\"]*\")", _contains_repl, _cond)
if '包含' in _cond:
    raise RuntimeError('「包含」用法示例：a[i] 包含 \'临时\'（让 a 列文本含“临时”的行进入「满足条件」）')

try:
    _cond_ast = ast.parse(_cond, mode='eval')
except SyntaxError as _err:
    raise RuntimeError('分割条件语法有误：' + str(_err) + '（示例：a[i] <= 0 or b[i] 包含 \'临时\'）')

_sub_exprs = []
for _node in ast.walk(_cond_ast):
    _is_compare = isinstance(_node, ast.Compare)
    _is_contains = isinstance(_node, ast.Call) and getattr(_node.func, 'id', '') == '_mod_contains_'
    if _is_compare or _is_contains:
        _seg = ast.get_source_segment(_cond, _node)
        if _seg and _seg not in _sub_exprs:
            _sub_exprs.append(_seg)
_sub_exprs = _sub_exprs[:20]


def _typed_column(_series):
    _series = _series.reset_index(drop=True)
    _conv = pd.to_numeric(_series, errors='coerce')
    if _conv.notna().sum() == _series.notna().sum() and _conv.notna().sum() > 0:
        return _conv.to_numpy(dtype=float)
    return _series.to_numpy(dtype=object)


_aliases = 'abcdefghijklmnopqrstuvwxyz'
_col_data = {}
for _idx, _c in enumerate(_cols):
    _col_data[_aliases[_idx]] = _typed_column(_df[_c])
_row_count = len(_df)


def _make_ns(_i):
    _ns = {'i': _i, '_EMPTY_': _EMPTY_, '_mod_contains_': _mod_contains_}
    _ns.update(_col_data)
    return _ns


_matched_indexes = []
_sub_hits = {}
for _i in range(_row_count):
    _ns = _make_ns(_i)
    try:
        _hit = bool(eval(_cond, {'__builtins__': {}}, _ns))
    except Exception as _err:
        raise RuntimeError('条件在第 ' + str(_i + 1) + ' 行执行失败：' + str(_err) + '（数值列才能用 <、>；文本列请用 包含 或 in）')
    if _hit:
        _matched_indexes.append(_i)
    for _seg in _sub_exprs:
        try:
            if bool(eval(_seg, {'__builtins__': {}}, dict(_ns))):
                _key = _pretty(_seg)
                _sub_hits[_key] = _sub_hits.get(_key, 0) + 1
        except Exception:
            pass

_report = {
    '原始行数': _row_count,
    '满足条件行数': len(_matched_indexes),
    '不满足条件行数': _row_count - len(_matched_indexes),
    '分割条件': _raw_cond,
    '各条件命中行数': _sub_hits,
}

_matched = _df.iloc[_matched_indexes].reset_index(drop=True)
_unmatched = _df.drop(index=_df.index[_matched_indexes]).reset_index(drop=True)
return {'满足条件': _matched, '不满足条件': _unmatched, 'report': _report}
